window.RP_SESSION={"id":"S-e1de0e037784","messages":[{"id":"RP-II-0033003","time":"2026-02-11T00:14:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033004","time":"2026-02-11T00:14:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"날씨가 아무 살짝 풀린 겨울날. 오늘같은 날 말을 타고 평지를 질주하면 정말 멋질 거 같네요.\n그런 날, 똥내나는 마굿간을 서성이는 이가 있었으니...! 토르번이었습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033005","time":"2026-02-11T00:15:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"한참을 눈치를 보며 마굿간 안으로 들어섰습니다. 그의 목표는...\n\n어찌됐건 북부에서 데려왔지만 아무도 태울 생각이 없어보여 애물단지가 되어버린 바이콘. 길드의 사람들은 아주 순결하고 고귀한가 보군요? (세션 설원의 꽃 참조)","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033006","time":"2026-02-11T00:15:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"토르번은 당근을 들고 천천히 조심스럽게 바이콘에게 다가갔습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033007","time":"2026-02-11T00:15:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033008","time":"2026-02-11T00:15:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'토르번 팔켄하인'의 매력 판정 :\n[1] + [0] = [1]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0033009","time":"2026-02-11T00:16:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"떠엉! 순식간에 토르번을 들이박는 바이콘! 그의 순결함이 증명되었을지도...!","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033010","time":"2026-02-11T00:16:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그대로 마굿간의 나무기둥에 튕겨나가 머리를 받고 쓰러집니다...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033011","time":"2026-02-11T00:16:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"의식이 점점 멀어지고... 눈이 감겨옵니다...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033012","time":"2026-02-11T00:16:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"레드.. 썬.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033013","time":"2026-02-11T00:17:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033014","time":"2026-02-11T00:17:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"https://www.youtube.com/watch?v=mce70-bplSI&list=RDmce70-bplSI&start_radio=1&t=299s","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033015","time":"2026-02-11T00:17:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"여기가 어디죠...?","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033016","time":"2026-02-11T00:18:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"눈덮인 들판 위, 바닥에 깔린 눈발이 조금 흩날리네요. 계절은 달라졌지만, 여러분에게도 어딘가 익숙할지도 모를 장소네요.\n\n아, 팔켄하인 영지에요. 겨울날의 고향입니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033017","time":"2026-02-11T00:19:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"시야가 조금 낮은 것이. 토르번은 자신의 몸을 이리저리 살펴봅니다. 작은 몸에 린넨 셔츠에 망토를 꽁꽁 싸맸군요.\n\n어릴 적의 일인가 보군요? 얼굴의 흉터도 없고, 머리도 짧고, 아주 미소년이네요!","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033018","time":"2026-02-11T00:20:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"익숙한 목소리가 들려오네요. 고용인 피올! 오늘도 고생이 많아요.\n\n\"도련님! 또 여기까지 나와계시네요! 날씨가 추워요. 그만 들어가요!\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033019","time":"2026-02-11T00:20:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"어....? 어어... 그래. 피올.\"\n\n토르번은 익숙한 듯 그녀에게 망토를 정돈 받고는 그녀를 따라가기 시작했습니다. 악몽은 벌써 두번째니까요!","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033020","time":"2026-02-11T00:22:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"오늘따라 팔켄하인 저택이 더 크게 보입니다. 아마도... 오늘의 일정은 훈련인가요?\n\n피올의 챙김을 받으며 옷을 갈아입고, 하인 게스펜이 장비들을 가져다주며 훈련장으로 발걸음을 옮깁니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033021","time":"2026-02-11T00:23:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"터엉! 터엉! 진검을 목인을 두들기며 혼자서 훈련을 시작합니다.\n\n12살의 나이라는 게 믿기지 않을 정도로 토르번의 검술은 뛰어났습니다.\n\n네 가지 자세들의 연계가 물흐르듯 이어지고, 눈을 속이는 듯한 현란한 보법으로 검로가 보이지도 않을 지경입니다.\n\n목인에게 훈련의 상처들이 계속 새겨집니다. 터엉! 타앙!","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033022","time":"2026-02-11T00:25:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"멀리서 형제들이 토르번을 보는 눈빛이 별로 달갑지는 않습니다.\n\n질투일까요? 아무래도 토르번은 왕따인 듯 합니다. 혼자서 목인의 어깨를 내려치는 소리와 비웃음소리인지 모를 잡담소리가 훈련장에 울려퍼집니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033023","time":"2026-02-11T00:27:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"이윽고 토르번의 검격이 멈추고, 숨을 고르며 땀을 닦았습니다. 그제서야 그들 중 누군가가 그에게 다가옵니다.\n\n팔켄하인의 장남인 클리브였습니다. 검은 셔츠에 곰처럼 커다란 덩치. 차가운 인상과 흉터, 타고난 강골같은 모습입니다. 등장만으로 분위기가 바뀌는 듯한 기분입니다.\n\n이미 17살에 완성된 전사. 자신의 투핸디드 소드를 뽑아들고서는 지친 기색인 토르번을 내려다보았습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033024","time":"2026-02-11T00:28:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"클리브가 잔뜩 깔은 목소리로 물었습니다.\n\n[계속 혼자 할 셈인가? 합을 조금 봐주도록 하지.]\n\n형제들은 뒤에서 키득거립니다. 별로 좋은 의도는 아닌 걸로 보이네요. 아마도 창피를 주려는 걸까요?\n\n하지만 맞이의 권유인 걸요? 거절했다간 어떤 식으로 괴롭힘을 키울지 모르니, 고개를 끄덕이며 토르번은 자세를 잡습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033025","time":"2026-02-11T00:29:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"설마, 진검 대련에서 험한 수작질을 부리겠어요? 열심히 검을 부딪히다가, 어느정도 바닥을 나뒹굴며 그들의 자존심을 채워주면 될 일이었습니다.\n\n하지만 정말 실증나는 일이었어요. 그는 그저 아버지와 어머니가 자신을 자랑스러워 할만큼 검을 휘두르는 것이 그의 전부였는 걸요.\n\n더이상 형제의 질투나, 견제 따위는 이골이 날 지경이었습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033026","time":"2026-02-11T00:31:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"[한 수 내어주마. 먼저 와보거라.]\n\n\"예. 형님.\"\n\n이윽고 토르번이 두 세번의 깊은 걸음에 거리가 순식간에 좁혀지더니 검이 맞부딪히며 강력한 금속음을 내었습니다.\n\n어라, 클리브의 표정이 이상합니다. 눈썹이 꿈틀거리며 미간이 찌푸러집니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033027","time":"2026-02-11T00:32:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그럼에도 불구하고, 두 개의 검과 두 쌍의 발은 멈추지를 않습니다. 자신의 예상과는 다른 토르번의 맹공에 클리브와 형제들의 웃음기가 싹 가십니다.\n\n찌르르르. 클리브의 손이 저려오는 것이, 이게 겨우 12살의 실력인가. 공포스럽고, 경악스럽습니다. 클리브의 일그러진 표정은 점차 당혹과 초조함으로 물들어갑니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033028","time":"2026-02-11T00:32:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그때, 훈련장의 2층에서 아버지가 나타납니다. 싸늘하고 무감정하게 내려다보는 그 시선에 형제들의 얼굴은 점점 굳어만 갑니다.\n\n그도 그럴게, 성인식도 치룬 기사 가문의 장남이 열 두살의 소년에게 밀리다니요.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033029","time":"2026-02-11T00:33:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"토르번의 검은 멈출 생각이 없습니다. 유려하게 클리브의 검을 몰아붙히고, 앞서가니 뒷서가니 하던 걸음에서 점점 토르번이 몰아붙이는 걸음이, 점점 클리브의 뒷걸음이 늘어났습니다.\n\n아기 맹수 따위가 아닙니다. 이미 수라를 넘어온, 마치 귀신을 상대하는 듯한 이 서늘한 느낌.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033030","time":"2026-02-11T00:35:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"쩌엉! 까앙! 기어코 강렬하다 못해 날카로운 소리가 훈련장을 울려퍼집니다. 그 곳에 모든 이들의 낯빛이 변합니다.\n\n검흔이 콧잔등을 가르고, 토르번의 검이 부러져 튕겨 나와 눈을 스치며 날아갔습니다.\n\n땡그랑. 바닥에 떨어진 검 조각이 튕겨져 나뒹굽니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033031","time":"2026-02-11T00:36:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"토르번의 반쪽 시야가 보이지 않습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033032","time":"2026-02-11T00:37:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"주르륵. 오른쪽 뺨부터 눈썹까지, 선명하게 일자로 그어진 검격, 그위를 갈라 새겨진 십자의 상처. 짙은 선홍빛의 액체가 끈적하게 흘러내립니다.\n\n\"...형님...?\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033033","time":"2026-02-11T00:38:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"클리브의 표정은 '이 할은 해내었다. 삼 할은 어떡하지. 사 할은 저질렀다.' 남은 이 할을 주위의 반응을 살피는 데에 사용하였습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033034","time":"2026-02-11T00:39:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"아버지는... 이내 몸을 돌려 사라지십니다. 그 건, 단순한 방조가 아니였습니다.\n\n큰아이, 어린아이 가리지 않고 형제들끼리 절벽 아래로 떨어뜨려 기어올라오는 한 마리만을 맹수로 키우겠다는 방침.\n\n그 정도로 팔켄하인 가는 몰려 있었을지도 모릅니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033035","time":"2026-02-11T00:39:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"토르번은 헛웃음만 나옵니다.\n\n\"허.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033036","time":"2026-02-11T00:40:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"아버지의 암묵적인 동의에, 형제들의 당혹은 곧 기세로 바뀌었습니다.\n\n클리브는 자신의 검 끝으로 토르번의 검을 가리켰습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033037","time":"2026-02-11T00:40:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"[토르번, 검을 들어라.]","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033038","time":"2026-02-11T00:41:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"제정신인가요?\n\n아니, 질문이 잘못되었군요.\n\n저들은 이미 제정신이 아닙니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033039","time":"2026-02-11T00:41:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033040","time":"2026-02-11T00:41:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"너무나 위태롭게 쌓인 선조의 명예가,\n\n고립된 설원의 한이,\n\n북부의 혹독함이,","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033041","time":"2026-02-11T00:42:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"아버지의 욕심이,\n\n형제들의 악랄함이,\n\n어설픈 소년의 재능이,\n\n여태 애써 괴롭힘을 무시해왔던 소년의 안일함이,","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033042","time":"2026-02-11T00:42:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"소년의 마음을 죽여갑니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033043","time":"2026-02-11T00:42:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...당신들은 제 정신이 아니야.\"\n\n희한하게도, 픽하고 웃음이 새어나옵니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033044","time":"2026-02-11T00:43:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"희한하게도, 머리가 뜨겁다 못해 차갑게 식어버립니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033045","time":"2026-02-11T00:43:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"희한하게도, 저들을 전부 죽여버릴 수 있다는 생각 조차 차오릅니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033046","time":"2026-02-11T00:44:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그 뒤는... 기억이 잘 나지 않습니다.\n\n아마도 저 멀리서 베릴 누나가 뛰어와 그들을 말렸던가요. 아마도, 부러진 검으로 그들에게 달려드는 토르번을 말렸을 겁니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033047","time":"2026-02-11T00:44:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...!\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033048","time":"2026-02-11T00:44:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033049","time":"2026-02-11T00:44:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...\n\n..\n\n.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033050","time":"2026-02-11T00:45:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"허억!\"\n\n토르번은 튀어오르듯 기절에서 깨어납니다.\n\n아찔한 머리를 부여잡습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033051","time":"2026-02-11T00:45:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...푸르륵.\"\n\n바이콘이 토르번을 비웃으며 콧방귀를 뀔 뿐이었습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033052","time":"2026-02-11T00:46:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...허, 지독한 악몽이군.\"\n\n토르번은 픽하고 웃어 넘깁니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033053","time":"2026-02-11T00:46:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"....그래서, 등 뒤에 태워줄 생각은 없나?\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033054","time":"2026-02-11T00:47:00+09:00","room":"RP II","name":"토르번 팔켄하인 / 꿈속 가족과 고용인 / 서술","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-7ba611cf90be"]},{"id":"RP-II-0033055","time":"2026-02-11T00:47:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
